# Self-contained Karzon bot release. Generated by build_github_release.py.
# Application code and JSON assets are embedded below; no upload folders needed.
import base64
import io
import json
import os
from pathlib import Path
import runpy
import sys
import tempfile
import zipfile

PAYLOAD = """"""

def unpack(destination):
    destination = Path(destination).resolve()
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as archive:
        for item in archive.infolist():
            target = (destination / item.filename).resolve()
            if not target.is_relative_to(destination):
                raise RuntimeError("Invalid release path")
            content = archive.read(item)
            if target.suffix == ".py":
                compile(content, item.filename, "exec")
            elif target.suffix == ".json":
                json.loads(content)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(content)

if __name__ == "__main__":
    if "--check" in sys.argv:
        with tempfile.TemporaryDirectory() as check_dir:
            unpack(check_dir)
        print("Release OK: all Python modules and JSON assets included.")
    else:
        root = Path(__file__).resolve().parent
        from dotenv import load_dotenv
        load_dotenv(root / ".env")
        # Local data survives restarting the self-contained application.
        os.environ.setdefault("DB_PATH", str(root / "database" / "karzoni_bot.db"))
        with tempfile.TemporaryDirectory(prefix="karzon-") as runtime:
            unpack(runtime)
            sys.path.insert(0, runtime)
            runpy.run_path(str(Path(runtime) / "main.py"), run_name="__main__")
